# Code generated by Claude
"""
Test check_success() (src/task_beaker_hotplate.py) on three hand-placed beaker states.

    source .venv/bin/activate
    python experiments/beaker_hotplate_success_test.py

No viewer, no rendering, one model. The robot is parked at the spawn pose, far from the bench. For each case the
beaker is teleported through its free joint (qpos), mj_forward is called, the scene is stepped for 1 s so the
beaker settles, and check_success() is read:
    1. beaker at its start pose            -> expect False
    2. beaker placed on the hotplate       -> expect True
    3. on the hotplate, tipped 45 degrees  -> expect False
Prints PASS/FAIL (PASS = the result matched the expectation) with each sub-condition and its measured value.
Exit code 1 if any case fails.
"""

import math
import sys
from pathlib import Path

import mujoco

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src import robot_specs  # noqa: E402
from src.task_config import TASK_CFG, SUCCESS_CFG  # noqa: E402
from src.task_beaker_hotplate import load_task, spawn_and_settle, bench_top_z, check_success  # noqa: E402


def main():
    sim = load_task(cameras=False)
    model, data = sim.model, sim.data
    st = spawn_and_settle(sim)
    top_site = data.site("hotplate_top").xpos.copy()
    jq = model.joint("task_beaker_free").qposadr[0]
    jv = model.joint("task_beaker_free").dofadr[0]
    top = bench_top_z(model)

    def place(xyz, quat):
        data.qpos[jq:jq + 3] = xyz
        data.qpos[jq + 3:jq + 7] = quat
        data.qvel[jv:jv + 6] = 0.0
        mujoco.mj_forward(model, data)

    def settle(seconds=1.0):
        for _ in range(int(round(seconds * robot_specs.PHYSICS_HZ))):
            data.ctrl[:] = st["hold"]
            data.qvel[st["base_dof"]:st["base_dof"] + 6] = 0.0
            mujoco.mj_step(model, data)

    half = math.radians(45) / 2
    cases = [
        ("1. beaker at its start pose", [*TASK_CFG["beaker_xy"], top + 0.002], [1, 0, 0, 0], False),
        ("2. beaker placed on the hotplate", [top_site[0], top_site[1], top_site[2] + 0.002], [1, 0, 0, 0], True),
        ("3. on the hotplate, tipped 45 deg", [top_site[0], top_site[1], top_site[2] + 0.03], [math.cos(half), math.sin(half), 0, 0], False),
    ]
    n_pass = 0
    for name, xyz, quat, expect in cases:
        place(xyz, quat)
        settle()
        ok, diag = check_success(model, data, SUCCESS_CFG)
        n_pass += ok == expect
        print(f"{'PASS' if ok == expect else 'FAIL'}  {name}: check_success -> {ok} (expected {expect})")
        for k, v in diag.items():
            print(f"        {k:18s} {'ok ' if v['ok'] else 'NOT'}  " + ", ".join(f"{kk}={vv}" for kk, vv in v.items() if kk != "ok"))
    print(f"{n_pass}/{len(cases)} cases PASS")
    sys.exit(0 if n_pass == len(cases) else 1)


if __name__ == "__main__":
    main()
